INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(1901, 'Exodus 16:15', 'Exodus', 16, 15, '&nbsp;چې کله بنى اِسرائيلو دا وليدل، نو هغوئ نۀ پېژندل چې دا څۀ شے دے او د يو بل نه يې تپوسونه کول، ”دا څۀ دى؟“ موسىٰ دوئ ته وفرمائيل، ”دا هغه روټۍ ده چې مالِک خُدائ تاسو له د خوړلو دپاره درکړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1902, 'Exodus 16:16', 'Exodus', 16, 16, '&nbsp;مالِک خُدائ حُکم کړے دے چې ستاسو هر يو کس به دومره راټولوى چې څومره خوړلے شى، تقريباً دوه کلو د خپل خاندان د هر يو کس دپاره.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1903, 'Exodus 16:17', 'Exodus', 16, 17, '&nbsp;بنى اِسرائيلو هم دغه شان وکړل، چا ډېره او چا لږه راټوله کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1904, 'Exodus 16:18', 'Exodus', 16, 18, '&nbsp;چې کله دوئ اندازه واخستله، چا چې ډېره راټوله کړې وه د هغۀ سره ډېره زياته نۀ وه او چا چې لږه راټوله کړې وه د هغۀ سره کمه نۀ وه. هر يو کس د خپل ضرورت په مطابق راټوله کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1905, 'Exodus 16:19', 'Exodus', 16, 19, '&nbsp;موسىٰ دوئ ته وفرمائيل، ”تر سحره پورې به هيڅ څوک هم په دې کښې څۀ نۀ پرېږدى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1906, 'Exodus 16:20', 'Exodus', 16, 20, '&nbsp;خو بعضې کسانو د موسىٰ خبره وانۀ ورېدله او لږه يې ترې نه پرېښوده. او بل سحر په کښې چينجى شوى وُو او سخا بوئ ترې نه تلو، نو موسىٰ دوئ ته په قهر شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1907, 'Exodus 16:21', 'Exodus', 16, 21, '&nbsp;هر سحر هر يو کس به د خپل ضرورت په مطابق راټولوله، او چې نمر به ګرم شو، نو څۀ هم چې په زمکه پاتې وُو نو هغه به ويلى شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1908, 'Exodus 16:22', 'Exodus', 16, 22, '&nbsp;په شپږمه ورځ دوئ يو په دوه روټۍ راټوله کړه، څلور کلو د هر يو کس دپاره. د قوم ټول مشران راغلل او موسىٰ ته يې د دې په حقله ووئيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1909, 'Exodus 16:23', 'Exodus', 16, 23, '&nbsp;نو هغۀ دوئ ته وفرمائيل، ”مالِک خُدائ حُکم کړے دے چې سبا د سبت مقدسه د آرام ورځ ده کومه چې مالِک خُدائ ته وقف ده، چې تاسو څۀ پخول غواړئ هغه نن پاخۀ کړئ او چې څۀ يشول غواړئ نو وې يشوئ. چې څۀ پاتې شى نو هغه د سبا دپاره پرېږدئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1910, 'Exodus 16:24', 'Exodus', 16, 24, '&nbsp;چې څنګه موسىٰ حُکم کړے وو، چې څۀ پاتې وه نو هغه يې د بلې ورځې پورې پرېښودله، او دا سخا نۀ شوه او نۀ په کښې چينجى وشول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1911, 'Exodus 16:25', 'Exodus', 16, 25, '&nbsp;موسىٰ وفرمائيل، ”دا نن وخورئ، ځکه چې نن د سبت يعنې د آرام ورځ ده، دا ورځ مالِک خُدائ ته وقف شوې ده او تاسو به بهر په زمکه هيڅ هم ونۀ مومئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1912, 'Exodus 16:26', 'Exodus', 16, 26, '&nbsp;تاسو به شپږ ورځې خوراک راټولوئ، خو اوومه ورځ د سبت ورځ ده، هيڅ خوراک به په کښې نۀ وى چې تاسو يې راټول کړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1913, 'Exodus 16:27', 'Exodus', 16, 27, '&nbsp;په اوومه ورځ څۀ خلق د خوراک راټولولو دپاره بهر لاړل، خو هغوئ هيڅ هم ونۀ موندل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1914, 'Exodus 16:28', 'Exodus', 16, 28, '&nbsp;نو مالِک خُدائ موسىٰ ته وفرمائيل، ”تر کومې پورې به تاسو زما حُکمونه او شريعت ماتوئ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1915, 'Exodus 16:29', 'Exodus', 16, 29, '&nbsp;ياد ساتئ چې ما مالِک خُدائ، تاسو له د سبت ورځ درکړې ده، نو په شپږمه ورځ به زۀ د همېشه دپاره تاسو له د دوو ورځو خوراک هم درکوم. په اوومه ورځ هر يو کس چې چرته هم وى هلته به ايساريږى او د خپل کور نه به بهر نۀ وځى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1916, 'Exodus 16:30', 'Exodus', 16, 30, '&nbsp;نو هغوئ په اوومه ورځ آرام وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1917, 'Exodus 16:31', 'Exodus', 16, 31, '&nbsp;د بنى اِسرائيلو قوم په دې خوراک من نوم کېښودو. دا د دڼيا د تخم په شان واړۀ وُو او رنګ يې سپين وو او خوند يې داسې وو لکه روټۍ چې په شاتو کښې پخه شوې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1918, 'Exodus 16:32', 'Exodus', 16, 32, '&nbsp;موسىٰ وفرمائيل، ”مالِک خُدائ حُکم کړے دے چې تاسو څۀ من د خپلو نسلونو دپاره وساتئ، نو هغوئ به دا روټۍ وګورى کومه چې هغۀ مونږ له په بيابان کښې د خوړلو دپاره راکړې ده کله چې هغۀ مونږ د مِصر مُلک نه راوويستلو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1919, 'Exodus 16:33', 'Exodus', 16, 33, '&nbsp;موسىٰ هارون ته وفرمائيل، ”يو لوښے واخله او د دوه کلو برابر من په کښې واچوه او د مالِک خُدائ په حضور کښې يې کېږده چې زمونږ د راتلونکو نسلونو دپاره وساتلے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1920, 'Exodus 16:34', 'Exodus', 16, 34, '&nbsp;چې څنګه مالِک خُدائ موسىٰ له حُکم ورکړے وو، هارون هغه د لوظ صندوق کښې د کاڼى تختو ته مخامخ کېښودو، چې بچ وساتلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1921, 'Exodus 16:35', 'Exodus', 16, 35, '&nbsp;بنى اِسرائيلو څلوېښت کاله من خوړل، تر دې پورې چې هغوئ د کنعان مُلک ته ورسېدل او هلته دېره شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1922, 'Exodus 16:36', 'Exodus', 16, 36, '&nbsp;(په هغه ورځو کښې به اومر او ايفه د څيزونو تَللو دپاره استعمالېدل لکه څنګه چې نن سبا کلو يا من استعماليږى، يو اومر د ايفه لسمه حِصه ده لکه څنګه چې کلو د من څلوېښتمه يا پنځوسمه حِصه ده.)', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1923, 'Exodus 17:1', 'Exodus', 17, 1, '&nbsp;د بنى اِسرائيلو ټول قوم د صين بيابان نه په سفر روان شولو او د مالِک خُدائ په حُکم يې د يو ځائ نه بل ځائ ته کډه وړله. دوئ په رفيديم کښې خېمې ولګولې، خو هلته د دې خلقو دپاره د څښلو اوبۀ نۀ وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1924, 'Exodus 17:2', 'Exodus', 17, 2, '&nbsp;نو په دې وجه خلق د موسىٰ سره په جګړه شول او وې وئيل، ”مونږ له د څښلو اوبۀ راکړه.“ موسىٰ دوئ ته وفرمائيل، ”تاسو ولې ما سره په جګړه يئ؟ تاسو ولې مالِک خُدائ په آزمېښت کښې اچوئ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1925, 'Exodus 17:3', 'Exodus', 17, 3, '&nbsp;خو خلق ډېر تږى وُو او موسىٰ ته وغورېدل. دوئ ووئيل، ”تا مونږ ولې د مِصر نه راوويستلو؟ د دې دپاره چې مونږ، زمونږ بچى او زمونږ څاروى د تندې نه ووژنې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1926, 'Exodus 17:4', 'Exodus', 17, 4, '&nbsp;نو موسىٰ مالِک خُدائ ته مِنت زارى وکړه او وې فرمائيل، ”زۀ دې خلقو سره څۀ وکړم؟ دوئ خو زما سنګسارولو ته تيار دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1927, 'Exodus 17:5', 'Exodus', 17, 5, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل، ”د ځان سره د بنى اِسرائيلو يو څو مشران روان کړه او د خلقو په وړاندې ځه. د ځان سره هغه امسا هم يوسه په کومه چې تا د نيل درياب وهلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1928, 'Exodus 17:6', 'Exodus', 17, 6, '&nbsp;او ګوره، زۀ به په سينا کښې په يو ګټ باندې ستا په وړاندې ولاړ يم. تۀ هغه ګټ په امسا ووهه او د هغه ګټ نه به د خلقو دپاره د څښلو اوبۀ راوځى.“ نو موسىٰ د بنى اِسرائيلو د مشرانو په مخکښې هم دغه شان وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1929, 'Exodus 17:7', 'Exodus', 17, 7, '&nbsp;نو هغۀ په دغه ځائ مسه (يعنې آزمېښت) او مريبه (يعنې جګړه) نوم کېښودو، ځکه چې بنى اِسرائيل په جګړه شول او مالِک خُدائ يې په آزمېښت کښې واچولو چې وې وئيل، ”مالِک خُدائ زمونږ مل دے کۀ نۀ دے؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1930, 'Exodus 17:8', 'Exodus', 17, 8, '&nbsp;بيا عماليقيان راغلل او په رفيديم کښې يې په بنى اِسرائيلو باندې حمله وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1931, 'Exodus 17:9', 'Exodus', 17, 9, '&nbsp;موسىٰ يشوَع ته وفرمائيل، ”يو څو سړى خوښ کړه او لاړ شه، سبا د عماليقيانو سره جنګ وکړه. زۀ به د غرۀ په سر ودرېږم او د خُدائ پاک طاقت لرونکې امسا به زما په لاس کښې وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1932, 'Exodus 17:10', 'Exodus', 17, 10, '&nbsp;يشوَع هم هغه شان وکړل چې څنګه ورته موسىٰ فرمائيلى وُو او عماليقيانو سره يې جنګ وکړو او موسىٰ، هارون او حُور د غرۀ سر ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1933, 'Exodus 17:11', 'Exodus', 17, 11, '&nbsp;تر کومې پورې چې موسىٰ لاسونه پورته نيولى وُو، اِسرائيليان په ګټه کښې وُو، خو چې کله هغۀ لاسونه لاندې کړل، نو عماليقيان په ګټه کښې شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1934, 'Exodus 17:12', 'Exodus', 17, 12, '&nbsp;چې کله د موسىٰ لاسونه ستړى شول، نو هارون او حُور ورله د کښېناستو دپاره يو کاڼے راوړو او هغوئ د هغۀ يو څنګ او بل څنګ ته ولاړ وُو او د هغۀ لاسونه يې پورته نيولى وُو او د نمرپرېواتو پورې د هغۀ لاسونه نېغ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1935, 'Exodus 17:13', 'Exodus', 17, 13, '&nbsp;نو داسې يشوَع عماليقيانو له پوره شکست ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1936, 'Exodus 17:14', 'Exodus', 17, 14, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل، ”دا فتح د ياد ساتلو دپاره د ځان سره وليکه. يشوَع ته دا واوروه چې زۀ به عماليقيان مکمل تباه کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1937, 'Exodus 17:15', 'Exodus', 17, 15, '&nbsp;موسىٰ يوه قربان‌ګاه جوړه کړه او په هغې يې ”مالِک خُدائ زما د فتحې جنډا ده“ نوم کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1938, 'Exodus 17:16', 'Exodus', 17, 16, '&nbsp;نو ځکه هغۀ وفرمائيل، ”د مالِک خُدائ جنډا اوچته ونيسئ. مالِک خُدائ به د همېشه دپاره د عماليقيانو خِلاف جنګ جارى ساتى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1939, 'Exodus 18:1', 'Exodus', 18, 1, '&nbsp;د موسىٰ سخر يترو، څوک چې د ميديان اِمام وو، هغۀ د هغه هر څۀ په حقله واورېدل چې خُدائ پاک د موسىٰ او د خپلو خلقو بنى اِسرائيلو دپاره کړى وُو او چې مالِک خُدائ هغوئ څنګه د مِصر نه راويستلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1940, 'Exodus 18:2', 'Exodus', 18, 2, '&nbsp;نو يترو موسىٰ له راغلو، د موسىٰ ښځه صفوره يې هم د ځان سره راوستله، کومه چې موسىٰ د خپلې سخرانې کره پرېښې وه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1941, 'Exodus 18:3', 'Exodus', 18, 3, '&nbsp;او ورسره د هغې دوه زامن جيرسوم او اِلى‌عزر هم وُو. موسىٰ فرمائيلى وُو، ”زۀ په پردى مُلک کښې مسافر يم.“ نو ځکه هغۀ په يو زوئ جيرسوم نوم کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1942, 'Exodus 18:4', 'Exodus', 18, 4, '&nbsp;هغۀ دا هم فرمائيلى وُو، ”زما د پلار خُدائ پاک زما مل وو او زۀ يې د مِصر د فِرعون نه بچ کړم چې هغۀ زۀ وژلم.“ نو ځکه هغۀ په بل زوئ اِلى‌عزر نوم کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1943, 'Exodus 18:5', 'Exodus', 18, 5, '&nbsp;يترو د موسىٰ د ښځې او د هغې د دوو زامنو سره بيابان ته راغلو چرته چې موسىٰ د خُدائ پاک غرۀ ته نزدې اوسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1944, 'Exodus 18:6', 'Exodus', 18, 6, '&nbsp;هغۀ موسىٰ له خبر ورولېږلو چې، ”زۀ ستا د ښځې او د دوو زامنو سره درروان يم،“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1945, 'Exodus 18:7', 'Exodus', 18, 7, '&nbsp;نو موسىٰ هغۀ سره مِلاوېدو دپاره بهر لاړو، د هغۀ په مخکښې د عزت نه ټيټ شو او ښُکل يې کړو. هغوئ د يو بل د خېر خېريت پوښتنه وکړه او بيا د موسىٰ خېمې ته دننه راغلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1946, 'Exodus 18:8', 'Exodus', 18, 8, '&nbsp;موسىٰ يترو ته هغه هر څۀ وفرمائيل کوم چې مالِک خُدائ د بنى اِسرائيلو په خاطر په فِرعون او د مِصر په خلقو کړى وُو. هغۀ ته يې د هغه تکليفونو په حقله هم وفرمائيل کوم چې په لاره کښې دوئ ته پېښ شوى وُو او دا هم چې مالِک خُدائ دوئ څنګه بچ کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
