(1988, 'Exodus 19:25', 'Exodus', 19, 25, '&nbsp;نو بيا موسىٰ خلقو له ورکوز شو او چې مالِک خُدائ څۀ فرمائيلى وُو هغه يې ورته وفرمائيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1989, 'Exodus 20:1', 'Exodus', 20, 1, '&nbsp;بيا خُدائ پاک کلام وکړو او هغه ټولې خبرې دا دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1990, 'Exodus 20:2', 'Exodus', 20, 2, '&nbsp;”زۀ مالِک خُدائ، ستاسو خُدائ پاک يم چا چې تاسو د مِصر د مُلک نه راوويستلئ، کوم چې د غلامۍ مُلک وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1991, 'Exodus 20:3', 'Exodus', 20, 3, '&nbsp;زما نه غېر د نورو معبودانو عبادت مۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1992, 'Exodus 20:4', 'Exodus', 20, 4, '&nbsp;د خپلو ځانونو دپاره بُتان مۀ جوړَوئ، د داسې يو څيز په شکل هم نه چې هغه پاس په آسمان کښې وى يا په زمکه وى يا کۀ هغه د زمکې لاندې په اوبو کښې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1993, 'Exodus 20:5', 'Exodus', 20, 5, '&nbsp;يو بُت ته هم چې سجده ونۀ لګوئ او نۀ يې عبادت وکړئ، ځکه چې زۀ مالِک خُدائ، ستاسو خُدائ پاک يو غېرتى خُدائ يم. زۀ هغه خلقو او د هغو اولادونو له د درېم او څلورم نسل پورې سزا ورکوم څوک چې زما نه کرکه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1994, 'Exodus 20:6', 'Exodus', 20, 6, '&nbsp;خو زۀ د هغه خلقو زرګونو نسلونو ته خپله نۀ بدلېدونکې مينه ښايم څوک چې زما سره مينه لرى او زما حُکمونه منى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1995, 'Exodus 20:7', 'Exodus', 20, 7, '&nbsp;زما نوم د غلطو مقصدونو دپاره مۀ استعمالوئ، ځکه چې زۀ، مالِک خُدائ، ستاسو خُدائ پاک به هغه چا له سزا ورکوم څوک چې زما نوم بې‌فائدې اخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1996, 'Exodus 20:8', 'Exodus', 20, 8, '&nbsp;د سبت ورځ ياده لرئ او دا مقدسه ګڼئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1997, 'Exodus 20:9', 'Exodus', 20, 9, '&nbsp;په شپږو ورځو کښې تاسو خپل کار روزګار کوئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1998, 'Exodus 20:10', 'Exodus', 20, 10, '&nbsp;خو اوومه ورځ د آرام ورځ ده چې ما ته وقف ده. په هغه ورځ به هيڅ څوک کار روزګار نۀ کوى، نۀ تاسو، نۀ ستاسو بچى، نۀ ستاسو غلامان، نۀ ستاسو څاروى او نۀ هغه مسافر کوم چې تاسو سره اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1999, 'Exodus 20:11', 'Exodus', 20, 11, '&nbsp;په شپږو ورځو کښې ما يعنې مالِک خُدائ زمکه، آسمان، سمندر او په دې کښې چې هر څۀ هم دى جوړ کړل، خو په اوومه ورځ يې څۀ ونۀ کړل. نو دا ځکه ما مالِک خُدائ د سبت ورځې له برکت ورکړو او مقدسه مې کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2000, 'Exodus 20:12', 'Exodus', 20, 12, '&nbsp;د خپل مور او پلار عزت کوئ، نو تاسو به په هغه مُلک کښې يو اوږد عمر تېر کړئ کوم چې زۀ درکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');